/**
 * Mini Calendar Component
 *
 * @copyright Copyright (c) 2025, Phillips Data, Inc.
 * @license http://www.blesta.com/license/ The Blesta License Agreement
 * @link http://www.blesta.com/ Blesta
 */
class MiniCalendar {
    constructor(elementSelector, options = {}) {
        this.element = document.querySelector(elementSelector);
        if (!this.element) {
            console.error('Mini calendar element not found:', elementSelector);
            return;
        }

        this.options = {
            calendarPageUrl: options.calendarPageUrl || 'calendar.html',
            ...options
        };

        this.currentDate = new Date();
        this.eventCounts = {};

        this.init();
    }

    /**
     * Initialize the mini calendar
     */
    async init() {
        await this.fetchEventCounts();
        this.render();
        this.attachEventListeners();
    }

    /**
     * Fetch event counts from server for the current month
     */
    async fetchEventCounts() {
        const year = this.currentDate.getFullYear();
        const month = this.currentDate.getMonth();

        const firstDay = new Date(year, month, 1);
        const lastDay = new Date(year, month + 1, 0);

        const startDate = this.formatDate(firstDay);
        const endDate = this.formatDate(lastDay);

        try {
            const response = await fetch(`${base_uri}main/geteventcounts/?start_date=${startDate}&end_date=${endDate}`);
            const data = await response.json();
            this.eventCounts = data || {};
        } catch (e) {
            console.error('Error fetching event counts:', e);
            this.eventCounts = {};
        }
    }

    /**
     * Render the calendar
     */
    render() {
        const year = this.currentDate.getFullYear();
        const month = this.currentDate.getMonth();
        const today = new Date();

        // Get month info
        const firstDay = new Date(year, month, 1);
        const lastDay = new Date(year, month + 1, 0);
        const daysInMonth = lastDay.getDate();
        const startingDayOfWeek = firstDay.getDay(); // 0 = Sunday

        // Build header
        const monthNames = ['January', 'February', 'March', 'April', 'May', 'June',
            'July', 'August', 'September', 'October', 'November', 'December'
        ];

        let html = `
            <div class="mini-calendar-header">
                <button class="mini-calendar-nav" data-action="prev">
                    <i class="bi bi-chevron-left"></i>
                </button>
                <div class="mini-calendar-month">${monthNames[month]} ${year}</div>
                <button class="mini-calendar-nav" data-action="next">
                    <i class="bi bi-chevron-right"></i>
                </button>
            </div>
            <div class="mini-calendar-grid">
                <!-- Day headers -->
                <div class="mini-calendar-day-header">Su</div>
                <div class="mini-calendar-day-header">Mo</div>
                <div class="mini-calendar-day-header">Tu</div>
                <div class="mini-calendar-day-header">We</div>
                <div class="mini-calendar-day-header">Th</div>
                <div class="mini-calendar-day-header">Fr</div>
                <div class="mini-calendar-day-header">Sa</div>
        `;

        // Add empty cells for days before month starts
        for (let i = 0; i < startingDayOfWeek; i++) {
            html += '<div class="mini-calendar-day empty"></div>';
        }

        // Add day cells
        for (let day = 1; day <= daysInMonth; day++) {
            const currentDateStr = this.formatDate(new Date(year, month, day));
            const eventCount = this.getEventCountForDate(currentDateStr);
            const isToday = today.getDate() === day &&
                today.getMonth() === month &&
                today.getFullYear() === year;

            const classes = ['mini-calendar-day'];
            if (isToday) classes.push('today');
            if (eventCount > 0) classes.push('has-events');

            html += `
                <div class="${classes.join(' ')}" data-date="${currentDateStr}">
                    <span class="mini-calendar-day-number">${day}</span>
                    ${eventCount > 0 ? `<span class="mini-calendar-event-badge">${eventCount > 9 ? '9+' : eventCount}</span>` : ''}
                </div>
            `;
        }

        html += '</div>'; // Close grid

        this.element.innerHTML = html;
    }

    /**
     * Attach event listeners (only called once in init)
     */
    attachEventListeners() {
        // Use event delegation - listen on the parent element
        this.element.addEventListener('click', (e) => {
            const navBtn = e.target.closest('[data-action]');
            if (navBtn) {
                const action = navBtn.dataset.action;
                if (action === 'prev') {
                    this.previousMonth();
                } else if (action === 'next') {
                    this.nextMonth();
                }
                return;
            }

            // Day clicks
            const dayCell = e.target.closest('.mini-calendar-day:not(.empty)');
            if (dayCell) {
                const date = dayCell.dataset.date;
                if (date) {
                    this.handleDayClick(date);
                }
            }
        });
    }

    /**
     * Handle day click
     */
    handleDayClick(date) {
        window.location.href = base_uri + `main/calendar/day/${date}`;
    }

    /**
     * Go to previous month
     */
    async previousMonth() {
        // Create new date to avoid mutation issues
        this.currentDate = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth() - 1, 1);
        await this.fetchEventCounts();
        this.render();
    }

    /**
     * Go to next month
     */
    async nextMonth() {
        // Create new date to avoid mutation issues
        this.currentDate = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth() + 1, 1);
        await this.fetchEventCounts();
        this.render();
    }

    /**
     * Get event count for a specific date
     */
    getEventCountForDate(dateStr) {
        return this.eventCounts[dateStr] || 0;
    }

    /**
     * Format date as YYYY-MM-DD
     */
    formatDate(date) {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    }

    /**
     * Refresh calendar (useful after external event changes)
     */
    async refresh() {
        await this.fetchEventCounts();
        this.render();
    }
}

// Auto-initialize mini calendars on page load
document.addEventListener('DOMContentLoaded', () => {
    const miniCalendarElement = document.querySelector('.mini-calendar');
    if (miniCalendarElement) {
        window.miniCalendar = new MiniCalendar('.mini-calendar');
    }
});
(function() {
    'use strict';

    document.addEventListener('DOMContentLoaded', () => {
        /**
         * Initialize bookmark button functionality (works on all pages)
         */
        function initBookmarkButton() {
            var bookmarkBtn = document.getElementById('bookmark-btn');
            if (!bookmarkBtn) return;

            bookmarkBtn.addEventListener('click', function(e) {
                e.preventDefault();

                var isBookmarked = this.classList.contains('bookmarked');
                var action = isBookmarked ? 'remove' : 'add';

                var params = {
                    action: action,
                    title: document.title.split("|")[0],
                    uri: window.location.pathname + window.location.search
                };

                // Create form data
                var formData = new FormData();
                for (var key in params) {
                    formData.append(key, params[key]);
                }

                // Send AJAX request
                var xhr = new XMLHttpRequest();
                xhr.open('POST', this.getAttribute('href'), true);
                xhr.onreadystatechange = function() {
                    if (xhr.readyState === 4) {
                        if (xhr.status === 200) {
                            try {
                                var data = JSON.parse(xhr.responseText);
                                var icon = bookmarkBtn.querySelector('i');
                                if (data.added) {
                                    bookmarkBtn.classList.add('bookmarked');
                                    if (icon) {
                                        icon.className = 'bi bi-star-fill';
                                    }
                                } else {
                                    bookmarkBtn.classList.remove('bookmarked');
                                    if (icon) {
                                        icon.className = 'bi bi-star';
                                    }
                                }
                            } catch (e) {
                                console.error('Error parsing response:', e);
                            }
                        }
                    }
                };
                xhr.send(formData);
            });
        }

        // Initialize bookmark button on all pages
        initBookmarkButton();

        /**
         * Check if we're on a page with sortable quick links (dashboard only)
         */
        const sortableQuickLinks = document.getElementById('sortable-quick-links');
        if (!sortableQuickLinks) {
            return;
        }

        /**
         * Initialize SortableJS on the quick links container
         */
        const sortable = new Sortable(sortableQuickLinks, {
            animation: 200,
            handle: '.action-drag-handle',
            ghostClass: 'sortable-ghost',
            chosenClass: 'sortable-chosen',
            dragClass: 'sortable-drag',
            easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
            draggable: '.side-content-link',
            onEnd: (evt) => {
                const order = getQuickLinksOrder();
                try {
                    localStorage.setItem('blesta-dashboard-quicklinks-order', JSON.stringify(order));
                } catch (e) {
                    // Nothing to do
                }
            }
        });

        /**
         * Get the current quick links order as an array
         * @returns {Array} Array of bookmark IDs in current order
         */
        function getQuickLinksOrder() {
            const order = [];

            // Get all quick link elements
            const allLinks = sortableQuickLinks.querySelectorAll('.side-content-link[data-bookmark-id]');

            allLinks.forEach((link) => {
                const bookmarkId = link.getAttribute('data-bookmark-id');
                if (bookmarkId) {
                    order.push(bookmarkId);
                }
            });

            return order;
        }

        /**
         * Check if there are no quick links and show/hide the alert
         */
        function checkEmptyQuickLinks() {
            const links = sortableQuickLinks.querySelectorAll('.side-content-link');
            const noQuicklinksAlert = document.getElementById('no-quicklinks-alert');

            if (links.length === 0) {
                noQuicklinksAlert.style.display = 'block';
            } else {
                noQuicklinksAlert.style.display = 'none';
            }
        }

        /**
         * Load quick links order from localStorage and reorder DOM elements
         */
        function loadQuickLinksOrder() {
            try {
                const savedOrder = localStorage.getItem('blesta-dashboard-quicklinks-order');
                if (!savedOrder) {
                    return; // No saved order
                }

                const order = JSON.parse(savedOrder);
                if (!Array.isArray(order) || order.length === 0) {
                    return;
                }

                // Get all quick link elements
                const allLinks = sortableQuickLinks.querySelectorAll('.side-content-link[data-bookmark-id]');
                const linkMap = new Map();

                allLinks.forEach(link => {
                    const bookmarkId = link.getAttribute('data-bookmark-id');
                    if (bookmarkId) {
                        linkMap.set(bookmarkId, link);
                    }
                });

                // Reorder elements based on saved order
                // Insert from the end to preserve correct sequence
                let insertBeforeElement = null;

                for (let i = order.length - 1; i >= 0; i--) {
                    const bookmarkId = order[i];
                    const link = linkMap.get(bookmarkId);

                    if (link) {
                        // Remove from current position
                        link.remove();

                        if (insertBeforeElement) {
                            // Insert before the previous element
                            sortableQuickLinks.insertBefore(link, insertBeforeElement);
                        } else {
                            // Append to the end (first iteration)
                            sortableQuickLinks.appendChild(link);
                        }

                        insertBeforeElement = link;
                    }
                }
            } catch (e) {
                // Nothing to do
            }
        }

        /**
         * Attach event listeners to quick link actions
         */
        function attachQuickLinkEventListeners() {
            // Edit buttons
            const editButtons = sortableQuickLinks.querySelectorAll('.btn-bookmark-edit');
            editButtons.forEach(btn => {
                btn.addEventListener('click', handleEditClick);
            });

            // Delete buttons
            const deleteButtons = sortableQuickLinks.querySelectorAll('.btn-bookmark-delete');
            deleteButtons.forEach(btn => {
                btn.addEventListener('click', handleDeleteClick);
            });

            // Double-click on title to edit
            const titles = sortableQuickLinks.querySelectorAll('.bookmark-title');
            titles.forEach(title => {
                title.addEventListener('dblclick', function(e) {
                    e.preventDefault();
                    const link = this.closest('.side-content-link');
                    const editBtn = link.querySelector('.btn-bookmark-edit');
                    if (editBtn) {
                        editBtn.click();
                    }
                });
            });
        }

        /**
         * Handle edit button click
         */
        function handleEditClick(e) {
            e.preventDefault();
            e.stopPropagation();

            const link = e.target.closest('.side-content-link');
            const bookmarkId = link.dataset.bookmarkId;
            const titleSpan = link.querySelector('.bookmark-title');
            const currentTitle = titleSpan.textContent;

            // Create input field
            const input = document.createElement('input');
            input.type = 'text';
            input.className = 'bookmark-edit-input';
            input.value = currentTitle;

            // Create save/cancel buttons
            const saveBtn = document.createElement('button');
            saveBtn.className = 'btn-bookmark-save';
            saveBtn.innerHTML = '<i class="bi bi-check"></i>';

            const cancelBtn = document.createElement('button');
            cancelBtn.className = 'btn-bookmark-cancel';
            cancelBtn.innerHTML = '<i class="bi bi-x"></i>';

            // Replace title with input
            titleSpan.style.display = 'none';
            titleSpan.insertAdjacentElement('afterend', input);
            titleSpan.insertAdjacentElement('afterend', cancelBtn);
            titleSpan.insertAdjacentElement('afterend', saveBtn);

            // Hide action buttons and drag handle
            const actions = link.querySelector('.bookmark-actions');
            const dragHandle = link.querySelector('.action-drag-handle');
            actions.style.display = 'none';
            dragHandle.style.display = 'none';

            // Prevent link navigation while in edit mode by removing href
            const originalHref = link.getAttribute('href');
            link.removeAttribute('href');
            link.style.cursor = 'default';

            input.focus();
            input.select();

            // Save function
            const save = () => {
                const newTitle = input.value.trim();
                if (newTitle && newTitle !== currentTitle) {
                    updateBookmarkTitle(bookmarkId, newTitle);
                    titleSpan.textContent = newTitle;
                }
                cleanup();
            };

            // Cancel function
            const cleanup = () => {
                input.remove();
                saveBtn.remove();
                cancelBtn.remove();
                titleSpan.style.display = '';
                actions.style.display = '';
                dragHandle.style.display = '';
                link.setAttribute('href', originalHref);
                link.style.cursor = '';
            };

            // Event listeners
            saveBtn.addEventListener('click', (e) => {
                e.preventDefault();
                e.stopPropagation();
                save();
            });

            cancelBtn.addEventListener('click', (e) => {
                e.preventDefault();
                e.stopPropagation();
                cleanup();
            });

            input.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    save();
                } else if (e.key === 'Escape') {
                    e.preventDefault();
                    cleanup();
                }
            });

            input.addEventListener('click', (e) => {
                e.stopPropagation();
            });

            input.addEventListener('blur', () => {
                // Delay to allow button clicks to register
                setTimeout(cleanup, 200);
            });
        }

        /**
         * Handle delete button click
         */
        function handleDeleteClick(e) {
            e.preventDefault();
            e.stopPropagation();

            const link = e.target.closest('.side-content-link');
            const bookmarkId = link.dataset.bookmarkId;
            const title = link.querySelector('.bookmark-title').textContent;

            // Set modal message with the quicklink title
            const messageElement = document.getElementById('delete-quicklink-message');
            messageElement.textContent = link.dataset.deleteMessage;

            // Get the modal and confirm button
            const modal = new bootstrap.Modal(document.getElementById('delete-quicklink-modal'));
            const confirmBtn = document.getElementById('confirm-delete-quicklink');

            // Remove any existing event listeners by cloning the button
            const newConfirmBtn = confirmBtn.cloneNode(true);
            confirmBtn.parentNode.replaceChild(newConfirmBtn, confirmBtn);

            // Add click handler for confirm button
            newConfirmBtn.addEventListener('click', () => {
                deleteBookmark(bookmarkId);
                link.remove();
                loadQuickLinksOrder();
                checkEmptyQuickLinks();
                modal.hide();
            });

            // Show the modal
            modal.show();
        }

        /**
         * Delete a bookmark via AJAX
         */
        function deleteBookmark(uri) {
            fetch(base_uri + 'main/updatequicklink/', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    'uri': uri,
                    'action': 'remove'
                })
            });
        }

        /**
         * Update a bookmark title via AJAX
         */
        function updateBookmarkTitle(uri, title) {
            fetch(base_uri + 'main/updatequicklink/', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    'uri': uri,
                    'title': title,
                    'action': 'add'
                })
            });
        }

        // Attach event listeners
        attachQuickLinkEventListeners();

        // Load saved order and reorder elements on page load
        loadQuickLinksOrder();

        // Check if there are no quick links on load
        checkEmptyQuickLinks();
    });
})();
(function() {
    document.addEventListener('DOMContentLoaded', function() {
        var sortableActions = document.getElementById('sortableActions');
        if (!sortableActions) return;

        var STORAGE_KEY = 'blesta-client-sidebar-actions';
        var VISIBLE_COUNT = 5;
        var expanded = false;

        /**
         * Get saved state from localStorage
         * @returns {Object} { order: [], expanded: false }
         */
        function getSavedState() {
            try {
                var saved = localStorage.getItem(STORAGE_KEY);
                if (saved) {
                    return JSON.parse(saved);
                }
            } catch (e) {
                // Storage not available
            }
            return {
                order: [],
                expanded: false
            };
        }

        /**
         * Save state to localStorage
         * @param {Array} order - Array of action IDs
         * @param {boolean} isExpanded - Whether actions are expanded
         */
        function saveState(order, isExpanded) {
            try {
                localStorage.setItem(STORAGE_KEY, JSON.stringify({
                    order: order,
                    expanded: isExpanded
                }));
            } catch (e) {
                // Storage not available
            }
        }

        /**
         * Get current order of action IDs
         * @returns {Array} Array of action IDs
         */
        function getCurrentOrder() {
            var order = [];
            var links = sortableActions.querySelectorAll('.side-content-link[data-action-id]');
            links.forEach(function(link) {
                var actionId = link.getAttribute('data-action-id');
                if (actionId) {
                    order.push(actionId);
                }
            });
            return order;
        }

        /**
         * Update visibility of actions based on position and expanded state
         */
        function updateVisibility() {
            var links = sortableActions.querySelectorAll('.side-content-link[data-action-id]');
            var toggleIcon = document.getElementById('toggleActionsIcon');
            var toggleText = document.getElementById('toggleActionsText');
            var toggleButton = document.getElementById('toggleActions');

            links.forEach(function(link, index) {
                if (index < VISIBLE_COUNT) {
                    // First 9 always visible
                    link.classList.remove('hidden-action');
                } else {
                    // Rest are hidden unless expanded
                    if (expanded) {
                        link.classList.remove('hidden-action');
                    } else {
                        link.classList.add('hidden-action');
                    }
                }
            });

            // Update toggle icon and text
            if (toggleIcon) {
                if (expanded) {
                    toggleIcon.classList.remove('bi-chevron-down');
                    toggleIcon.classList.add('bi-chevron-up');
                } else {
                    toggleIcon.classList.remove('bi-chevron-up');
                    toggleIcon.classList.add('bi-chevron-down');
                }
            }

            if (toggleText && toggleButton) {
                var textMore = toggleButton.getAttribute('data-text-more');
                var textLess = toggleButton.getAttribute('data-text-less');
                toggleText.textContent = expanded ? textLess : textMore;
            }
        }

        /**
         * Restore order from saved state
         */
        function restoreOrder() {
            var state = getSavedState();
            expanded = state.expanded;

            if (!state.order || state.order.length === 0) {
                updateVisibility();
                return;
            }

            // Build map of all action links
            var linkMap = new Map();
            var links = sortableActions.querySelectorAll('.side-content-link[data-action-id]');
            links.forEach(function(link) {
                var actionId = link.getAttribute('data-action-id');
                if (actionId) {
                    linkMap.set(actionId, link);
                }
            });

            // Find the toggle button to insert before
            var toggleButton = sortableActions.querySelector('.side-content-link-toggle');

            // Reorder elements
            state.order.forEach(function(actionId) {
                var link = linkMap.get(actionId);
                if (link) {
                    link.remove();
                    if (toggleButton) {
                        sortableActions.insertBefore(link, toggleButton);
                    } else {
                        sortableActions.appendChild(link);
                    }
                }
            });

            updateVisibility();
        }

        /**
         * Initialize SortableJS
         */
        new Sortable(sortableActions, {
            animation: 200,
            handle: '.action-drag-handle',
            ghostClass: 'sortable-ghost',
            chosenClass: 'sortable-chosen',
            dragClass: 'sortable-drag',
            easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
            draggable: '.side-content-link',
            filter: '.side-content-link-toggle',
            onEnd: function() {
                updateVisibility();
                saveState(getCurrentOrder(), expanded);
            }
        });

        /**
         * Toggle button click handler with slide animation
         */
        var toggleButton = document.getElementById('toggleActions');
        if (toggleButton) {
            toggleButton.addEventListener('click', function(e) {
                e.preventDefault();

                var willExpand = !expanded;

                // Capture current height
                var startHeight = sortableActions.scrollHeight;
                sortableActions.style.overflow = 'hidden';
                sortableActions.style.height = startHeight + 'px';

                if (willExpand) {
                    // Expanding: update visibility first, then animate
                    expanded = true;
                    updateVisibility();

                    // Measure target height
                    sortableActions.style.height = 'auto';
                    var endHeight = sortableActions.scrollHeight;
                    sortableActions.style.height = startHeight + 'px';

                    // Animate
                    sortableActions.style.transition = 'height 400ms ease';
                    requestAnimationFrame(function() {
                        sortableActions.style.height = endHeight + 'px';
                    });

                    setTimeout(function() {
                        sortableActions.style.height = '';
                        sortableActions.style.overflow = '';
                        sortableActions.style.transition = '';
                        saveState(getCurrentOrder(), expanded);
                    }, 400);
                } else {
                    // Collapsing: measure target height first, animate, then hide items
                    // Temporarily apply hidden classes to measure collapsed height
                    var links = sortableActions.querySelectorAll('.side-content-link[data-action-id]');
                    links.forEach(function(link, index) {
                        if (index >= VISIBLE_COUNT) {
                            link.classList.add('hidden-action');
                        }
                    });

                    // Measure collapsed height
                    sortableActions.style.height = 'auto';
                    var endHeight = sortableActions.scrollHeight;

                    // Restore visible state for animation
                    links.forEach(function(link, index) {
                        if (index >= VISIBLE_COUNT) {
                            link.classList.remove('hidden-action');
                        }
                    });
                    sortableActions.style.height = startHeight + 'px';

                    // Animate
                    sortableActions.style.transition = 'height 400ms ease';
                    requestAnimationFrame(function() {
                        sortableActions.style.height = endHeight + 'px';
                    });

                    setTimeout(function() {
                        // Now actually update the state and hide items
                        expanded = false;
                        updateVisibility();
                        sortableActions.style.height = '';
                        sortableActions.style.overflow = '';
                        sortableActions.style.transition = '';
                        saveState(getCurrentOrder(), expanded);
                    }, 400);
                }
            });
        }

        // Restore saved order on init
        restoreOrder();
    });
})();
/**
 * Notifications Component
 *
 * @copyright Copyright (c) 2025, Phillips Data, Inc.
 * @license http://www.blesta.com/license/ The Blesta License Agreement
 * @link http://www.blesta.com/ Blesta
 */
(function() {
    'use strict';

    /**
     * Initialize notifications polling functionality
     */
    function initNotificationsPolling() {
        var notificationsDropdown = document.getElementById('notifications-dropdown');
        if (!notificationsDropdown) return;

        // Function to fetch notifications
        function fetchNotifications() {
            // Check if notifications dropdown is open (has .show class)
            var notificationDropdown = notificationsDropdown.querySelector('.notification-dropdown');
            if (notificationDropdown && notificationDropdown.classList.contains('show')) {
                // Don't update if dropdown is open
                return;
            }

            var xhr = new XMLHttpRequest();
            xhr.open('GET', public_uri + 'api/notifications', true);
            xhr.onreadystatechange = function() {
                if (xhr.readyState === 4) {
                    if (xhr.status === 200) {
                        try {
                            var response = JSON.parse(xhr.responseText);
                            if (response.response && response.response.html) {
                                // Create a temporary div to parse the HTML
                                var tempDiv = document.createElement('div');
                                tempDiv.innerHTML = response.response.html;
                                var newDropdown = tempDiv.firstElementChild;

                                // Replace the notifications dropdown with the new one
                                notificationsDropdown.parentNode.replaceChild(newDropdown, notificationsDropdown);

                                // Update our reference to the new element
                                notificationsDropdown = newDropdown;

                                // Re-attach any event listeners if needed
                                attachNotificationEvents();
                            }
                        } catch (e) {
                            console.error('Error parsing notifications response:', e);
                        }
                    }
                }
            };
            xhr.send();
        }

        // Function to attach event listeners to notification elements
        function attachNotificationEvents() {
            // Re-attach any event listeners that might have been lost
            var notificationItems = document.querySelectorAll('.notification-item');
            var dismissButtons = document.querySelectorAll('.notification-dismiss');
            var markAllReadButton = document.querySelector('.notification-mark-all-read');
            if (!notificationItems || !dismissButtons || !markAllReadButton) return;

            // Add click handlers to notification items
            notificationItems.forEach(function(item) {
                item.addEventListener('click', function(e) {
                    e.stopPropagation();
                    var notificationId = this.dataset.notificationId || this.closest('.notification-item').dataset.notificationId;
                    if (notificationId) {
                        markNotificationRead(notificationId);
                    }
                });
            });

            // Add click handlers to dismiss buttons
            dismissButtons.forEach(function(button) {
                button.addEventListener('click', function(e) {
                    e.stopPropagation();
                    var notificationId = this.dataset.notificationId || this.closest('.notification-item').dataset.notificationId;
                    if (notificationId) {
                        this.closest('.notification-item').remove();
                        dismissNotification(notificationId);
                    }
                });
            });

            // Add click handler to mark all as read button
            markAllReadButton.addEventListener('click', function(e) {
                e.stopPropagation();
                markAllNotificationsRead();
            });
        }

        // Function to mark notification as read
        function markNotificationRead(notificationId) {
            var xhr = new XMLHttpRequest();
            xhr.open('POST', public_uri + 'api/notifications/' + notificationId + '/read', true);
            xhr.onreadystatechange = function() {
                if (xhr.readyState === 4) {
                    if (xhr.status === 200) {
                        // Open notification
                        openNotification(notificationId);

                        // Update only if it is unread
                        var item = document.querySelector('.notification-item[data-notification-id="' + notificationId + '"]');
                        if (item && !item.classList.contains('unread')) {
                            return;
                        }

                        // Update notification badge
                        updateNotificationBadge();

                        // Remove .unread class from notification
                        if (item) {
                            item.classList.remove('unread');
                        }
                    }
                }
            };
            xhr.send();
        }

        // Function to dismiss/delete notification
        function dismissNotification(notificationId) {
            var xhr = new XMLHttpRequest();
            xhr.open('DELETE', public_uri + 'api/notifications/' + notificationId + '/delete', true);
            xhr.onreadystatechange = function() {
                if (xhr.readyState === 4) {
                    if (xhr.status === 200) {
                        // Update notification badge
                        updateNotificationBadge();
                    }
                }
            };
            xhr.send();
        }

        // Function to mark all notifications as read
        function markAllNotificationsRead() {
            var xhr = new XMLHttpRequest();
            xhr.open('POST', public_uri + 'api/notifications/read-all', true);
            xhr.onreadystatechange = function() {
                if (xhr.readyState === 4) {
                    if (xhr.status === 200) {
                        // Remove unread class from all notification items
                        var notificationItems = document.querySelectorAll('.notification-item.unread');
                        notificationItems.forEach(function(item) {
                            item.classList.remove('unread');
                        });

                        // Update notification badge
                        updateNotificationBadge();

                        // Hide the mark all read button since there are no unread notifications
                        var markAllReadButton = document.querySelector('.notification-mark-all-read');
                        if (markAllReadButton) {
                            markAllReadButton.style.display = 'none';
                        }
                    }
                }
            };
            xhr.send();
        }

        // Function to open/fetch a specific notification
        function openNotification(notificationId) {
            var xhr = new XMLHttpRequest();
            xhr.open('GET', public_uri + 'api/notifications', true);
            xhr.onreadystatechange = function() {
                if (xhr.readyState === 4) {
                    if (xhr.status === 200) {
                        try {
                            var response = JSON.parse(xhr.responseText);

                            if (response.response && response.response.notifications) {
                                // Find notification with matching id
                                var notification = response.response.notifications.find(function(notif) {
                                    return notif.id == notificationId;
                                });

                                if (notification) {
                                    // Update modal label if it exists
                                    var modalLabel = document.getElementById('notification-modal-label');
                                    if (modalLabel && notification.title) {
                                        modalLabel.textContent = notification.title;
                                    }

                                    // Update modal body if it exists
                                    var modalBody = document.getElementById('notification-modal-body');
                                    if (modalBody && notification.message) {
                                        // Remove HTML tags, convert newlines to <br>, and linkify URLs
                                        var tempDiv = document.createElement('div');
                                        tempDiv.textContent = notification.message;
                                        var strippedMessage = tempDiv.textContent;
                                        var message = strippedMessage.replace(/\n/g, '<br>');

                                        // Linkify URLs (http and https only)
                                        message = message.replace(
                                            /(\bhttps?:\/\/[-A-Z0-9+&@#\/%?=~_|!:,.;]*[-A-Z0-9+&@#\/%=~_|])/gim,
                                            '<a href="$1" target="_blank" rel="noopener noreferrer">$1</a>'
                                        );

                                        modalBody.innerHTML = message;
                                    }

                                    // Set URL in footer, if available
                                    var modalFooter = document.getElementById('notification-modal-footer');
                                    if (modalFooter) {
                                        modalFooter.style.display = 'none';
                                    }

                                    if (notification.url) {
                                        var modalLink = document.getElementById('notification-modal-link');
                                        if (modalFooter && modalLink) {
                                            modalFooter.style.display = '';
                                            modalLink.href = notification.url;
                                        }
                                    }

                                    // Show the modal
                                    var modal = new bootstrap.Modal(document.getElementById('notification-modal'));
                                    if (modal) {
                                        modal.show();
                                    }
                                }
                            }
                        } catch (e) {
                            console.error('Error parsing notification response:', e);
                        }
                    }
                }
            };
            xhr.send();
        }

        // Function to update notification badge count
        function updateNotificationBadge() {
            var badge = notificationsDropdown.querySelector('.notification-badge');
            if (!badge) return;

            var xhr = new XMLHttpRequest();
            xhr.open('GET', public_uri + 'api/notifications', true);
            xhr.onreadystatechange = function() {
                if (xhr.readyState === 4) {
                    if (xhr.status === 200) {
                        try {
                            var response = JSON.parse(xhr.responseText);
                            if (response.response && typeof response.response.unread_count !== 'undefined') {
                                var unread_count = parseInt(response.response.unread_count) || 0;

                                if (unread_count > 0) {
                                    badge.textContent = unread_count;
                                    badge.style.display = 'inline-block';
                                } else {
                                    badge.style.display = 'none';
                                }
                            }
                        } catch (e) {
                            console.error('Error parsing notifications response:', e);
                        }
                    }
                }
            };
            xhr.send();
        }

        // Attach events on initial load
        attachNotificationEvents();

        // Initial fetch
        fetchNotifications();

        // Set up polling every 60 seconds
        setInterval(fetchNotifications, 30 * 1000);
    }

    // Initialize notifications polling when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initNotificationsPolling);
    } else {
        initNotificationsPolling();
    }
})();
/**
 * Dashboard Widgets Component
 *
 * @copyright Copyright (c) 2026, Phillips Data, Inc.
 * @license http://www.blesta.com/license/ The Blesta License Agreement
 * @link http://www.blesta.com/ Blesta
 */
class DashboardWidgets {
    constructor(container_selector, options) {
        this.container = document.querySelector(container_selector);
        if (!this.container) {
            return;
        }

        var defaults = {
            fetch_uri: null,
            update_uri: null,
            toggle_uri: null,
            resize_uri: null
        };

        this.options = Object.assign({}, defaults, options);
        this.widgets_data = {};

        this.init();
    }

    /**
     * Initialize the dashboard
     */
    async init() {
        await this.loadWidgets();
        this.bindGuiEvents();
    }

    /**
     * Load widgets from server
     */
    async loadWidgets() {
        if (!this.options.fetch_uri) {
            return;
        }

        try {
            var response = await fetch(this.options.fetch_uri, {
                headers: {
                    'X-Requested-With': 'XMLHttpRequest'
                }
            });
            var widgets = await response.json();
            this.widgets_data = widgets;

            // Create placeholders and load each widget
            for (var widget_id in widgets) {
                if (!widgets.hasOwnProperty(widget_id)) {
                    continue;
                }

                var widget_info = widgets[widget_id];

                var placeholder = document.createElement('div');
                placeholder.id = 'widget-container-' + widget_id;
                this.container.appendChild(placeholder);

                this.fetchWidgetContent(widget_id, widget_info);
            }
        } catch (e) {
            console.error('Error loading widgets:', e);
        }
    }

    /**
     * Fetch individual widget content
     */
    async fetchWidgetContent(widget_id, widget_data) {
        try {
            var response = await fetch(widget_data.uri, {
                headers: {
                    'X-Requested-With': 'XMLHttpRequest'
                }
            });
            var text = await response.text();
            var html_content;

            // Try to parse as JSON first, fall back to raw HTML
            try {
                var data = JSON.parse(text);
                html_content = data.content;
            } catch (parse_error) {
                html_content = text;
            }

            var temp = document.createElement('div');
            temp.innerHTML = html_content;
            var widget_element = temp.querySelector('section.card');

            if (!widget_element) {
                return;
            }

            // Set data-width attribute from widget state
            var width = widget_data.width || 'full';
            widget_element.setAttribute('data-width', width);

            // Handle closed widget state
            if (!widget_data.open) {
                var header = widget_element.querySelector('div.card-header:last-of-type');
                if (header) {
                    header.classList.add('close');
                }
                widget_element.classList.add('collapsed');

                // Hide widget content
                this.hideWidgetContent(widget_element);

                // Toggle icons
                var arrow = widget_element.querySelector('div.card-header a.arrow');
                if (arrow) {
                    this.toggleIcons(arrow);
                }
            }

            // Toggle widget-width icons for half-width widgets
            if (width === 'half') {
                var resizeLink = widget_element.querySelector('div.card-header a.widget-width');
                if (resizeLink) {
                    this.toggleIcons(resizeLink);
                }
            }

            // Get badge value for closed widgets
            this.getWidgetBadge(widget_element);

            // Replace placeholder with entire widget content (including scripts)
            var placeholder = document.getElementById('widget-container-' + widget_id);
            if (placeholder) {
                // Collect scripts before moving nodes
                var scripts = [];
                temp.querySelectorAll('script').forEach(function(script) {
                    scripts.push(script.textContent);
                });

                // Replace with all content
                placeholder.replaceWith(...temp.childNodes);

                // Execute scripts (innerHTML doesn't execute them)
                scripts.forEach(function(script_content) {
                    var new_script = document.createElement('script');
                    new_script.textContent = script_content;
                    document.body.appendChild(new_script);
                });
            }
        } catch (e) {
            console.error('Error loading widget ' + widget_id + ':', e);
        }
    }

    /**
     * Hide widget content for closed widgets
     */
    hideWidgetContent(element) {
        var headers = element.querySelectorAll('.card-header.close');
        headers.forEach(function(header) {
            var tab_content = header.parentElement.querySelector('.card-content');
            if (tab_content) {
                tab_content.style.display = 'none';
            }
        });
    }

    /**
     * Toggle hidden class on icon elements
     */
    toggleIcons(element) {
        var icons = element.querySelectorAll('i');
        icons.forEach(function(icon) {
            if (icon.classList.contains('hidden')) {
                icon.classList.remove('hidden');
            } else {
                icon.classList.add('hidden');
            }
        });
    }

    /**
     * Fetch and display badge for closed widgets
     */
    async getWidgetBadge(widget) {
        // Remove any existing badge
        var existing_badge = widget.querySelector('.card-header .badge');
        if (existing_badge) {
            existing_badge.remove();
        }

        // Only fetch badge if widget is closed
        var header = widget.querySelector('div.card-header');
        if (!header || !header.classList.contains('close')) {
            return;
        }

        // Find badge URI
        var badge_input = widget.querySelector('input[name="badge_uri"]');
        if (!badge_input) {
            return;
        }

        var badge_uri = badge_input.value;
        if (!badge_uri) {
            return;
        }

        try {
            var response = await fetch(badge_uri, {
                headers: {
                    'X-Requested-With': 'XMLHttpRequest'
                }
            });
            var data = await response.text();

            if (data) {
                var h2 = widget.querySelector('h2');
                if (h2) {
                    var badge = document.createElement('strong');
                    badge.className = 'badge badge-danger';
                    badge.textContent = data;
                    h2.appendChild(badge);
                }
            }
        } catch (e) {
            console.error('Error fetching badge:', e);
        }
    }

    /**
     * Bind all GUI events
     */
    bindGuiEvents() {
        this.initSortable();

        // Use event delegation for all widget events
        this.container.addEventListener('click', this.handleClick.bind(this));

        // Cursor style on hover
        this.container.addEventListener('mouseover', function(e) {
            var header = e.target.closest('.card-header');
            if (header) {
                header.style.cursor = 'move';
            }
        });
    }

    /**
     * Handle click events via delegation
     */
    handleClick(e) {
        // AJAX link requests in widgets
        var ajax_link = e.target.closest('a.ajax');
        if (ajax_link) {
            e.preventDefault();
            this.handleAjaxLink(ajax_link);
            return;
        }

        // Expand/collapse toggle
        var arrow = e.target.closest('a.arrow');
        if (arrow) {
            e.preventDefault();
            this.handleToggle(arrow);
            return;
        }

        // Full screen toggle
        var full_screen = e.target.closest('a.full_screen');
        if (full_screen) {
            e.preventDefault();
            this.handleFullScreen(full_screen);
            return;
        }

        // Widget resize
        var resize = e.target.closest('a.widget-width');
        if (resize) {
            e.preventDefault();
            this.handleResize(resize);
            return;
        }
    }

    /**
     * Initialize Sortable.js for drag-drop
     */
    initSortable() {
        var self = this;

        if (typeof Sortable === 'undefined' || !this.options.update_uri) {
            return;
        }

        new Sortable(this.container, {
            animation: 200,
            handle: '.card-header',
            ghostClass: 'sortable-ghost',
            chosenClass: 'sortable-chosen',
            dragClass: 'sortable-drag',
            easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
            onEnd: function() {
                self.saveWidgetOrder();
            }
        });
    }

    /**
     * Handle expand/collapse toggle
     */
    handleToggle(arrow) {
        var self = this;
        var card = arrow.closest('.card');
        var tab_content = card.querySelector('.card-content');

        if (!tab_content) {
            return;
        }

        // Determine current state: widget is closed if card has 'collapsed' class
        var is_currently_closed = card.classList.contains('collapsed');
        var will_be_open = is_currently_closed;

        if (is_currently_closed) {
            // Remove collapsed class but set display none directly
            // so slideToggle can detect it properly and animate expand
            card.classList.remove('collapsed');
            tab_content.style.display = 'none';
        }

        // Slide toggle animation
        blestaSlideToggle(tab_content, 400, function() {
            self.toggleIcons(arrow);

            if (!will_be_open) {
                card.classList.add('collapsed');
            }

            // Save state to server (true = open, false = closed)
            if (self.options.toggle_uri) {
                var widget_id = card.id;
                self.ajaxRequest('POST', self.options.toggle_uri, widget_id + '=' + will_be_open);
            }

            // Update badge
            self.getWidgetBadge(card);
        });
    }

    /**
     * Handle full screen toggle
     */
    handleFullScreen(button) {
        var card = button.closest('div.card-header').parentElement;
        card.classList.toggle('full-screen');
        this.toggleIcons(button);
    }

    /**
     * Handle widget resize
     */
    handleResize(button) {
        var card = button.closest('.card');
        var current_width = card.getAttribute('data-width') || 'full';
        var new_width = current_width === 'full' ? 'half' : 'full';
        var widget_id = card.id;

        // Update data attribute
        card.setAttribute('data-width', new_width);

        // Toggle icons
        this.toggleIcons(button);

        // Save to server
        if (this.options.resize_uri && widget_id) {
            this.ajaxRequest('POST', this.options.resize_uri, {
                widget_id: widget_id,
                width: new_width
            });
        }
    }

    /**
     * Handle AJAX link requests
     */
    async handleAjaxLink(link) {
        var parent_box = link.closest('section.card');
        var url = link.getAttribute('href');

        // If not in a widget, continue as normal
        if (!parent_box) {
            return;
        }

        try {
            var response = await fetch(url, {
                headers: {
                    'X-Requested-With': 'XMLHttpRequest'
                }
            });

            var data = await response.json();

            // Replace content in the widget
            if (data.replacer == null) {
                // No specific replacer, replace entire box with parsed HTML
                var temp = document.createElement('div');
                temp.innerHTML = data.content;

                // If the content contains a single root element, replace with it
                if (temp.children.length === 1) {
                    parent_box.replaceWith(temp.children[0]);
                } else {
                    // Multiple elements or mixed content - replace parent_box with all content
                    parent_box.replaceWith(...temp.childNodes);
                }
            } else {
                // Replace specific element within the box
                var target = parent_box.querySelector(data.replacer);
                if (target) {
                    target.innerHTML = data.content;
                }
            }
        } catch (e) {
            console.error('AJAX request failed:', e);
        }
    }

    /**
     * Save widget order to server
     */
    saveWidgetOrder() {
        var widget_data = [];
        var widgets = this.container.querySelectorAll('section, .card');

        widgets.forEach(function(card, index) {
            var id = card.id;
            var width = card.getAttribute('data-width') || 'full';
            var column = null;

            if (width === 'half') {
                column = index % 2;
            }

            if (id) {
                widget_data.push({
                    id: id,
                    width: width,
                    column: column,
                    order: index
                });
            }
        });

        this.ajaxRequest('POST', this.options.update_uri, {
            widget: widget_data
        });
    }

    /**
     * Generic AJAX request helper
     */
    ajaxRequest(method, url, data) {
        var options = {
            method: method,
            headers: {
                'X-Requested-With': 'XMLHttpRequest'
            }
        };

        if (data) {
            if (typeof data === 'object') {
                options.headers['Content-Type'] = 'application/x-www-form-urlencoded';
                options.body = this.serializeObject(data);
            } else {
                options.headers['Content-Type'] = 'application/x-www-form-urlencoded';
                options.body = data;
            }
        }

        fetch(url, options).catch(function(e) {
            console.error('AJAX request failed:', e);
        });
    }

    /**
     * Serialize object to URL-encoded string
     */
    serializeObject(obj, prefix) {
        var pairs = [];
        for (var key in obj) {
            if (!obj.hasOwnProperty(key)) {
                continue;
            }

            var param_key = prefix ? prefix + '[' + key + ']' : key;
            var value = obj[key];

            if (typeof value === 'object' && value !== null) {
                pairs.push(this.serializeObject(value, param_key));
            } else {
                pairs.push(encodeURIComponent(param_key) + '=' + encodeURIComponent(value));
            }
        }
        return pairs.join('&');
    }
}

